-- DRE gerencial por competência. Caixa e pagamentos permanecem separados.
alter table commerce_accounts_payable add column if not exists competencia_em date,add column if not exists natureza_dre text;
update commerce_accounts_payable set competencia_em=coalesce(competencia_em,created_at::date),natureza_dre=coalesce(natureza_dre,case when entry_id is not null then 'compra_estoque' else 'nao_classificada' end);
alter table commerce_accounts_payable alter column competencia_em set default current_date,alter column competencia_em set not null,alter column natureza_dre set default 'nao_classificada',alter column natureza_dre set not null;
alter table commerce_accounts_payable add constraint commerce_payable_natureza_dre_check check(natureza_dre in('compra_estoque','despesa_operacional','despesa_administrativa','despesa_comercial','despesa_financeira','despesa_tributaria','outras_despesas','nao_classificada'));
create index commerce_payable_competencia_idx on commerce_accounts_payable(business_id,competencia_em,natureza_dre) where status<>'cancelada';

create function commerce_relatorio_dre(p_inicio date,p_fim date) returns table(ordem integer,codigo text,descricao text,valor numeric,grupo text)
language sql stable security invoker set search_path=public as $$
with vendas as(select coalesce(sum(total),0)::numeric receita from commerce_sales where owner_id=commerce_owner_atual() and status in('concluida','devolvida_parcial','devolvida') and competencia_em>=p_inicio::timestamptz and competencia_em<(p_fim+1)::timestamptz),
devolucoes as(select coalesce(sum(valor),0)::numeric valor from commerce_sale_returns where owner_id=commerce_owner_atual() and created_at>=p_inicio::timestamptz and created_at<(p_fim+1)::timestamptz),
cmv_vendas as(select coalesce(sum(i.quantidade*i.custo_unitario_snapshot),0)::numeric valor from commerce_sale_items i join commerce_sales s on s.id=i.sale_id where s.owner_id=commerce_owner_atual() and s.status in('concluida','devolvida_parcial','devolvida') and s.competencia_em>=p_inicio::timestamptz and s.competencia_em<(p_fim+1)::timestamptz),
cmv_devolvido as(select coalesce(sum(ri.quantidade*si.custo_unitario_snapshot),0)::numeric valor from commerce_sale_return_items ri join commerce_sale_returns r on r.id=ri.return_id join commerce_sale_items si on si.id=ri.sale_item_id where r.owner_id=commerce_owner_atual() and r.created_at>=p_inicio::timestamptz and r.created_at<(p_fim+1)::timestamptz),
despesas as(select natureza_dre,coalesce(sum(valor),0)::numeric valor from commerce_accounts_payable where owner_id=commerce_owner_atual() and status<>'cancelada' and competencia_em between p_inicio and p_fim and natureza_dre<>'compra_estoque' group by natureza_dre),
totais as(select v.receita,d.valor devolucoes,v.receita-d.valor receita_liquida,cv.valor-cd.valor cmv from vendas v cross join devolucoes d cross join cmv_vendas cv cross join cmv_devolvido cd),
linhas as(select 10 ordem,'RB' codigo,'Receita bruta de vendas' descricao,receita valor,'receita' grupo from totais union all select 20,'DEV','(-) Devoluções',-devolucoes,'deducao' from totais union all select 30,'RL','Receita líquida',receita_liquida,'subtotal' from totais union all select 40,'CMV','(-) Custo das mercadorias vendidas',-cmv,'custo' from totais union all select 50,'MB','Margem bruta',receita_liquida-cmv,'subtotal' from totais union all select 60,'DO','(-) Despesas operacionais',-coalesce((select valor from despesas where natureza_dre='despesa_operacional'),0),'despesa' union all select 61,'DA','(-) Despesas administrativas',-coalesce((select valor from despesas where natureza_dre='despesa_administrativa'),0),'despesa' union all select 62,'DC','(-) Despesas comerciais',-coalesce((select valor from despesas where natureza_dre='despesa_comercial'),0),'despesa' union all select 63,'DF','(-) Despesas financeiras',-coalesce((select valor from despesas where natureza_dre='despesa_financeira'),0),'despesa' union all select 64,'DT','(-) Despesas tributárias informadas',-coalesce((select valor from despesas where natureza_dre='despesa_tributaria'),0),'despesa' union all select 65,'OD','(-) Outras despesas',-coalesce((select valor from despesas where natureza_dre='outras_despesas'),0),'despesa' union all select 66,'NC','Contas ainda não classificadas',coalesce((select valor from despesas where natureza_dre='nao_classificada'),0),'alerta'),
resultado as(select coalesce(sum(valor) filter(where ordem in(30,40,60,61,62,63,64,65)),0) valor from linhas)
select * from linhas union all select 90,'RG','Resultado gerencial',valor,'resultado' from resultado order by ordem;$$;
revoke all on function commerce_relatorio_dre(date,date) from public,anon;grant execute on function commerce_relatorio_dre(date,date) to authenticated;
